import numpy as np
try:
    from scipy.optimize import curve_fit
    have=True
except Exception as ex:
    have=False; print(ex)
if have:
    fams={
     'a-b*e^n': (lambda e,a,b,n: a-b*e**n, [13,2,1]),
     'a*(1-(e/b)^n)': (lambda e,a,b,n: a*(1-(e/b)**n), [13,5,1.5]),
     'a*cos(b e)+c': (lambda e,a,b,c: a*np.cos(b*e)+c, [13,0.5,0]),
     'a*exp(-b e)-c e': (lambda e,a,b,c: a*np.exp(-b*e)-c*e, [13,0.2,0.5]),
     'a*log(b/e)': (lambda e,a,b: a*np.log(b/e), [3,5]),
     'a*(b-e)^n': (lambda e,a,b,n: a*(b-e)**n, [1,5,1]),
     'a-b*e-c*e^2 ^p': (lambda e,a,b,c: a-b*e-c*e**2, [13,2,0.1]),
     'a-b*sinh? ': (lambda e,a,b,c: a-b*np.sinh(c*e), [13,1,0.3]),
    }
    for k,(f,p0) in fams.items():
        try:
            p,_=curve_fit(f,eps,sigma,p0=p0,maxfev=20000)
            r=sigma-f(eps,*p)
            print(k, "NMSE %.3e"%(np.mean(r**2)/np.var(sigma)), p.round(4))
        except Exception as ex:
            print(k,"fail",ex)
